const nav=[['index.html','Home'],['discover.html','Discover'],['worlds.html','Worlds'],['characters.html','Characters'],['journal.html','Journal'],['collection.html','My Collection'],['muses.html','Muses'],['atelier.html','Atelier'],['garden.html','Moon Garden'],['studio.html','Character Builder'],['portraits.html','Create Identity']];
const stories=[{id:'ember',title:'Ember & the Last Sun',genre:'Fantasy',tag:'THE EDITOR’S PICK',desc:'When the sun begins to fade, a reluctant swordswoman carries the last spark across a sleeping kingdom.',color:'#c86547',pos:'0% 0%'},{id:'neon',title:'Neon Reverie',genre:'Sci-Fi',tag:'AFTER HOURS',desc:'A memory courier discovers a message that could wake an entire city from its beautiful dream.',color:'#408f9d',pos:'50% 0%'},{id:'moon',title:'Where the Moon Sleeps',genre:'Fantasy',tag:'SLOW DOWN',desc:'In a valley where wishes bloom as flowers, a quiet astronomer searches for a missing constellation.',color:'#8b6dba',pos:'100% 0%'},{id:'tide',title:'Children of the Tide',genre:'Adventure',tag:'CHASE THE HORIZON',desc:'An unlikely crew follows a map drawn by the ocean itself. Every island holds another impossible secret.',color:'#d19a54',pos:'0% 100%'},{id:'train',title:'Five Stops to Spring',genre:'Slice of Life',tag:'FEEL SOMETHING',desc:'Two strangers take the same train every evening. One forgotten sketchbook changes their route.',color:'#be7d91',pos:'50% 100%'},{id:'sky',title:'The Sky Between Us',genre:'Adventure',tag:'WANDER FURTHER',desc:'Above the clouds, a wandering cartographer finds an island that no one remembers.',color:'#619b81',pos:'100% 100%'}];
let saved;try{saved=JSON.parse(localStorage.getItem('yoru-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{saved=[]}
const file=location.pathname.split('/').pop()||'index.html';const page=nav.find(n=>n[0]===file)?.[1]||'Home';
const icon='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M17 3a9 9 0 1 0 4 13A8 8 0 0 1 17 3Z"/></svg>';
function card(s,i){return `<article class="story-card"><button class="art art-${s.id}" style="--accent:${s.color};--pos:${s.pos}" data-detail="${s.id}" aria-label="Explore ${s.title}"><span class="art-no">0${i+1}</span><span class="art-genre">${s.genre}</span></button><div class="card-meta"><span>${s.tag}</span><button class="save ${saved.includes(s.id)?'is-saved':''}" data-save="${s.id}" aria-label="${saved.includes(s.id)?'Remove from':'Save to'} collection">${saved.includes(s.id)?'♥':'♡'}</button></div><h3><button data-detail="${s.id}">${s.title}</button></h3><p>${s.desc}</p></article>`}
function intro(eyebrow,title,text){return `<section class="page-intro"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></section>`}
const header=`<header><a class="brand" href="index.html">${icon}<span>yoru<span class="brand-dot">.</span></span><small>夜</small></a><button class="menu-toggle" aria-label="Toggle navigation" aria-expanded="false">☰</button><nav aria-label="Main navigation">${nav.filter(([url])=>['index.html','portraits.html','discover.html','muses.html'].includes(url)).sort((a,b)=>['index.html','portraits.html','discover.html','muses.html'].indexOf(a[0])-['index.html','portraits.html','discover.html','muses.html'].indexOf(b[0])).map(([url,label])=>`<a class="${page===label?'active':''} ${url==='portraits.html'?'main-studio-link':''}" href="${url}">${label}</a>`).join('')}<details class="nav-more"><summary>Explore</summary><div>${nav.filter(([url])=>!['index.html','portraits.html','discover.html','muses.html'].includes(url)).map(([url,label])=>`<a class="${page===label?'active':''}" href="${url}">${label}</a>`).join('')}</div></details></nav><a class="header-action" href="discover.html">Find your next world <span>↗</span></a></header>`;
const footer=`<footer><a class="brand" href="index.html">${icon}<span>yoru.</span></a><p>A little escape. A bigger imagination.</p><span>Original worlds, made for the curious. © ${new Date().getFullYear()} Yoru</span><a href="journal.html">Stay curious ↗</a></footer>`;
let content='';
if(page==='Home')content=`<section class="hero"><div class="hero-shade"></div><div class="hero-copy"><div class="eyebrow"><span class="tiny-line"></span> CREATE YOUR ANIME IDENTITY</div><h1>Your world.<br>Your alter ego<span>.</span></h1><p>Choose a beautiful portrait. Make it yours.<br class="desktop"> Take home a matching profile picture, card, and banner.</p><div class="hero-actions"><a class="button primary" href="portraits.html">Create your identity <span>↗</span></a><a class="text-button" href="portraits.html?surprise=1"><span class="play">✧</span> Surprise me</a></div><div class="hero-foot"><span>CURATED WITH CURIOSITY. MADE FOR YOU.</span><div><span class="hero-index">01</span><span class="hero-track"></span><span>06</span></div></div></div><div class="hero-caption"><span>THE ART OF GETTING LOST</span><span>夜の向こうへ — Beyond the night</span></div><a class="scroll-cue" href="#featured">SCROLL TO DISCOVER ↓</a></section><div class="ticker"><span>FOR THE DAYDREAMERS</span><b>✦</b><span>THE LATE-NIGHT WATCHERS</span><b>✦</b><span>THE “JUST ONE MORE” PEOPLE</span><b>✦</b><span>WELCOME TO YOUR WORLD</span><b>✦</b></div><section id="featured" class="section"><div class="section-head"><div><div class="eyebrow">YOUR NEXT OBSESSION STARTS HERE</div><h2>Out of this world.</h2></div><a class="subtle-link" href="discover.html">Explore all stories ↗</a></div><div class="card-grid">${stories.slice(0,3).map(card).join('')}</div></section><section class="manifesto"><span class="eyebrow">NOT JUST ANOTHER UNIVERSE.</span><h2>A feeling you<br>haven’t found yet.</h2><p>Stories can take you anywhere. Start with a world that speaks to you, meet someone extraordinary, and make a little space for wonder.</p><a class="button" href="worlds.html">Take the scenic route ↗</a><span class="big-kanji" aria-hidden="true">夢</span></section>`;
if(page==='Discover')content=intro('THE DISCOVERY ROOM','Find your next <em>obsession.</em>','Six original stories. A thousand places your imagination can go.')+`<section class="section browse"><div class="browse-tools"><div class="filters" aria-label="Filter stories">${['All','Fantasy','Sci-Fi','Adventure','Slice of Life'].map((x,i)=>`<button class="filter ${i?'':'selected'}" data-filter="${x}">${x}</button>`).join('')}</div><label class="search">⌕ <input id="search" placeholder="Search stories…" aria-label="Search stories"></label></div><div class="results-meta" aria-live="polite">6 stories to get lost in</div><div id="results" class="card-grid">${stories.map(card).join('')}</div></section>`;
if(page==='Worlds')content=intro('PLACES THAT FEEL IMPOSSIBLE','Leave ordinary <em>behind.</em>','Pick a horizon. Every world has a different kind of magic.')+`<section class="section worlds-grid">${[stories[0],stories[1],stories[5]].map((s,i)=>`<a href="discover.html?genre=${encodeURIComponent(s.genre)}" class="world-panel art art-${s.id}" style="--pos:${s.pos};--accent:${s.color}"><span>WORLD 0${i+1} / ${s.genre.toUpperCase()}</span><div><h2>${['The Sunfall Kingdom','New Hikari, 2096','The Floating Archipelago'][i]}</h2><p>${['Ancient forests. Ember skies. One last light.','Rain-soaked streets and borrowed memories.','Follow the rivers that flow into the sky.'][i]}</p><b>Enter this world ↗</b></div></a>`).join('')}</section>`;
if(page==='Characters')content=intro('THE SOULS OF OUR STORIES','Meet the <em>unforgettable.</em>','Heroes, dreamers, and beautifully imperfect people. All characters are original creations.')+`<section class="section"><div class="character-grid">${[['Akira','The keeper of the last light','ember','Brave enough to begin. Human enough to be afraid.'],['Ren','The memory courier','neon','He remembers everyone’s past. Except his own.'],['Luna','The constellation finder','moon','She looks for answers where others see only stars.'],['Kai','The horizon chaser','tide','A terrible navigator with an extraordinary instinct.'],['Hana','The everyday daydreamer','train','Collecting little moments, one sketch at a time.'],['Sora','The sky cartographer','sky','There is always something beyond the edge of the map.']].map(([name,role,id,desc])=>{let s=stories.find(s=>s.id===id);return `<article class="character"><button class="art art-${id}" style="--pos:${s.pos};--accent:${s.color}" data-detail="${id}" aria-label="Read about ${name}"></button><div><span class="eyebrow">${role}</span><h2>${name}</h2><p>${desc}</p><button class="subtle-link" data-detail="${id}">Meet their story ↗</button></div></article>`}).join('')}</div></section>`;
if(page==='Journal')content=intro('NOTES FROM THE OTHER SIDE','A moment to <em>wander.</em>','Small reflections on the stories we love, and the worlds we carry with us.')+`<section class="section journal-list">${[['The quiet magic of the in-between','Why train rides, empty streets, and ordinary afternoons can be the most memorable scenes.','train','4 MIN READ'],['Building a world you want to get lost in','A field guide to impossible places that somehow feel like home.','sky','5 MIN READ'],['Why we root for imperfect heroes','The cracks in a character are often where the light gets in.','ember','3 MIN READ']].map(([title,desc,id,time],i)=>{let s=stories.find(s=>s.id===id);return `<article class="journal-entry"><div class="art art-${id}" style="--pos:${s.pos};--accent:${s.color}"></div><div><span class="eyebrow">ESSAY 0${i+1} · ${time}</span><h2>${title}</h2><p>${desc}</p><button class="subtle-link" data-essay="${i}">Read the reflection ↗</button></div></article>`}).join('')}</section>`;
if(page==='My Collection')content=intro('A SMALL CORNER OF YOUR UNIVERSE','Keep the <em>good ones.</em>','Save a story with the heart button. Your collection stays in this browser.')+`<section class="section"><div id="collection" class="card-grid">${stories.filter(s=>saved.includes(s.id)).map(card).join('')}</div><div class="empty-state" ${saved.length?'hidden':''}><span>♡</span><h2>Your next favourite is out there.</h2><p>Find something that stays with you, and save it here.</p><a class="button primary" href="discover.html">Discover a story ↗</a></div></section>`;
if(page==='Character Builder')content=studioContent();
if(page==='Create Identity')content=portraitContent();
if(['Muses','Atelier','Moon Garden'].includes(page))content=extraContent(page);
if(page==='Home')content+=`<section class="section studio-promo"><span class="eyebrow">YOUR NEXT STORY HAS YOUR NAME ON IT</span><h2>Don’t just meet a character.<br>Become one.</h2><p>Discover your anime persona, make it yours, and take your world with you.</p><a class="button primary" href="portraits.html">Create my anime persona ↗</a></section>`;
if(page==='Home')content+=`<section class="section new-chapter"><span class="eyebrow">A NEW CHAPTER / THE PORTRAIT CLUB</span><h2>A little mystery. A little magnetism.</h2><p>Meet the muses, play with the light, or slip away to the Moon Garden.</p><div class="chapter-links"><a href="muses.html">01 · Muses ↗</a><a href="atelier.html">02 · Atelier ↗</a><a href="garden.html">03 · Moon Garden ↗</a></div></section>`;
document.getElementById('app').innerHTML=header+`<main>${content}</main>`+footer+`<dialog id="detail"><button class="dialog-close" aria-label="Close">×</button><div id="dialog-content"></div></dialog><div class="toast" role="status" aria-live="polite"></div>`;
document.title=`${page} — Yoru`;
let activeFilter='All';function filter(){const query=document.getElementById('search').value.toLowerCase();let items=stories.filter(s=>(activeFilter==='All'||s.genre===activeFilter)&&`${s.title} ${s.desc} ${s.genre}`.toLowerCase().includes(query));document.getElementById('results').innerHTML=items.length?items.map(card).join(''):'<p class="no-results">No stories found. Try another search or genre.</p>';document.querySelector('.results-meta').textContent=`${items.length} ${items.length===1?'story':'stories'} to get lost in`;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===activeFilter))}
document.querySelector('#search')?.addEventListener('input',filter);if(page==='Discover'){let g=new URLSearchParams(location.search).get('genre');if(g&&stories.some(s=>s.genre===g)){activeFilter=g;filter()}}
const essays=[['The quiet magic of the in-between','We remember the battle. But sometimes, what stays with us is the train ride home. A character leans against a window. The landscape passes. For a moment, nothing needs to happen.','Those pauses give a story room to breathe. They let us notice a small kindness, a change in the weather, or a feeling the character has not found words for yet.','Try paying attention to the transitions next time. The walk between two places can tell you as much as the destination.'],['Building a world you want to get lost in','An extraordinary world begins with ordinary details. Where do people buy breakfast? What happens when it rains? Which street takes you home?','The floating islands in The Sky Between Us began with a question: how would people find each other if the ground kept moving? Maps became letters. Rivers became roads.','A believable world does not need an explanation for every mystery. It needs a few familiar things that make you want to stay long enough to discover the rest.'],['Why we root for imperfect heroes','Akira does not begin her journey because she feels ready. She begins because someone has to carry the light, and she happens to be there.','A character who never doubts can be impressive. A character who doubts and still takes the next step can make us feel understood.','The best kind of courage is rarely loud. Sometimes it is a quiet decision to try again tomorrow.']];
document.addEventListener('click',e=>{let b=e.target.closest('[data-save]');if(b){let id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('yoru-saved',JSON.stringify(saved))}catch{}document.querySelectorAll(`[data-save="${id}"]`).forEach(x=>{x.classList.toggle('is-saved',saved.includes(id));x.textContent=saved.includes(id)?'♥':'♡';x.setAttribute('aria-label',(saved.includes(id)?'Remove from':'Save to')+' collection')});let t=document.querySelector('.toast');t.textContent=saved.includes(id)?'Added to your universe ♡':'Removed from your collection';t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2200);if(page==='My Collection'){document.querySelector('#collection').innerHTML=stories.filter(s=>saved.includes(s.id)).map(card).join('');document.querySelector('.empty-state').hidden=!!saved.length}return}b=e.target.closest('[data-filter]');if(b){activeFilter=b.dataset.filter;filter()}b=e.target.closest('[data-detail]');if(b){let s=stories.find(s=>s.id===b.dataset.detail);document.getElementById('dialog-content').innerHTML=`<div class="dialog-art art art-${s.id}" style="--pos:${s.pos};--accent:${s.color}"></div><div class="dialog-copy"><span class="eyebrow">ORIGINAL STORY CONCEPT · ${s.genre}</span><h2>${s.title}</h2><p>${s.desc}</p><p class="note">An original world created for Yoru. Explore the concept and save it for inspiration.</p><button class="button primary" data-save="${s.id}">${saved.includes(s.id)?'♥':'♡'}</button></div>`;document.querySelector('dialog').showModal()}b=e.target.closest('[data-essay]');if(b){let a=essays[+b.dataset.essay];document.getElementById('dialog-content').innerHTML=`<div class="dialog-copy essay"><span class="eyebrow">THE YORU JOURNAL</span><h2>${a[0]}</h2>${a.slice(1).map(p=>`<p>${p}</p>`).join('')}</div>`;document.querySelector('dialog').showModal()}if(e.target.closest('.dialog-close'))document.querySelector('dialog').close();if(e.target.closest('.menu-toggle')){let b=document.querySelector('.menu-toggle');let open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open)}});
document.querySelector('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});

initExtras();

initStudio();

initPortraits();
